output_text:
[
  {
    "id": "return_cart_to_service",
    "text": "Anyone who takes a shopping cart is obliged to return it to the customer-service cart return before leaving.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "customer_service_cart_return": "at(0,1)",
        "pushing_cart": "hasCart",
        "cart_parked_at_customer_service": "cartAt(0,1)"
      },
      "events": {
        "take_cart_from_entrance": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        },
        "return_cart_to_customer_service": {
          "pre": {
            "and": [
              "customer_service_cart_return",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_customer_service"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart_from_entrance",
      "discharge": "return_cart_to_customer_service"
    }
  },
  {
    "id": "only_leave_cart_at_service",
    "text": "It is forbidden to put a shopping cart down anywhere except the customer-service cart return.",
    "abstraction": {
      "state_properties": {
        "customer_service_cart_return": "at(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "leave_cart_outside_return": {
          "pre": {
            "and": [
              "pushing_cart",
              "LEAVE_CART",
              {
                "not": "customer_service_cart_return"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "It is forbidden to leave the supermarket while still pushing or holding a shopping cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "at_exit": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "at_exit",
              "pushing_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "cart_required_for_item_pickup",
    "text": "Customers are forbidden to take shelf items unless they currently have a shopping cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers are forbidden to carry grocery items by hand rather than placing them in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "not_using_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_into_hands": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "not_using_cart"
            ]
          },
          "post": "carrying_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "pickup_into_hands"
        ]
      }
    }
  },
  {
    "id": "must_take_cart_at_start",
    "text": "At the beginning of a shopping trip, the customer is obliged to check out a cart from the entrance cart station.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "checkout_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "checkout_entrance_cart"
    }
  },
  {
    "id": "return_cart_after_shopping",
    "text": "After picking up any required item with a cart, the customer is obliged to return the cart to customer service before exiting.",
    "abstraction": {
      "state_properties": {
        "customer_service_cart_return": "at(0,1)",
        "pushing_cart": "hasCart",
        "cart_parked_at_customer_service": "cartAt(0,1)"
      },
      "events": {
        "item_loaded_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "pushing_cart"
            ]
          },
          "post": "pushing_cart"
        },
        "cart_returned_after_shopping": {
          "pre": {
            "and": [
              "customer_service_cart_return",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "cart_parked_at_customer_service",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_loaded_into_cart",
      "discharge": "cart_returned_after_shopping"
    }
  },
  {
    "id": "carts_barred_from_exit_side",
    "text": "Shopping carts are forbidden in the exit-side travel corridor, so customers must park the cart before walking to the exit.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "exit_side_corridor": {
          "or": [
            "at(7,1)",
            "at(8,1)",
            "at(9,1)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_exit_side_corridor": {
          "and": [
            "pushing_cart",
            "exit_side_corridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_side_corridor"
    }
  }
]
